package com.bitedash.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id") private Order order; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="food_item_id") private FoodItem foodItem; @Column(nullable=false) private int quantity; @Column(name="unit_price",nullable=false,precision=10,scale=2) private BigDecimal unitPrice; protected OrderItem(){} public OrderItem(Order o,FoodItem f,int q){order=o;foodItem=f;quantity=q;unitPrice=f.getPrice();} public Long getId(){return id;} public FoodItem getFoodItem(){return foodItem;} public int getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;} }
